// Do not edit this file as it will be overwritten if HAMR codegen is rerun

//! Uninterpreted component action abstractions, used ONLY by the
//! Commutativity VCs. Verus proves those VCs for ALL interpretations of
//! the action fns; the real component behaviors are one interpretation
//! (components only write their declared out ports/state, and outputs
//! depend only on the read scope), so a discharged Commutativity VC
//! establishes the Isabelle `execIndependent` obligation.

#![allow(non_snake_case)]
#![allow(unused_variables)]

use data::*;
use vstd::prelude::*;

use crate::system_state::SystemState;
use crate::write_frames::*;

verus! {

// -- 'above_top.Impl'_Instance.A_sub.a --

pub uninterp spec fn outer_a_action_Output(Input: i32, Output: i32) -> i32;

/** "OUTER_A fires": every written field is determined by the read scope;
  * everything else is framed.
  */
pub open spec fn outer_a_fire(pre: SystemState, post: SystemState) -> bool
{
  post.system_output == outer_a_action_Output(pre.top_output, pre.system_output)
  && outer_a_global_write_frame(pre, post)
}

// -- 'above_top.Impl'_Instance.top_sub.A_sub.a --

pub uninterp spec fn a_action_Output(Input: i32, Output: i32) -> i32;

/** "A fires": every written field is determined by the read scope;
  * everything else is framed.
  */
pub open spec fn a_fire(pre: SystemState, post: SystemState) -> bool
{
  post.top_a_output == a_action_Output(pre.system_input, pre.top_a_output)
  && a_global_write_frame(pre, post)
}

// -- 'above_top.Impl'_Instance.top_sub.B_sub.b --

pub uninterp spec fn b_action_Output(Input: i32, Output: i32) -> i32;

/** "B fires": every written field is determined by the read scope;
  * everything else is framed.
  */
pub open spec fn b_fire(pre: SystemState, post: SystemState) -> bool
{
  post.top_b_output == b_action_Output(pre.top_a_output, pre.top_b_output)
  && b_global_write_frame(pre, post)
}

// -- 'above_top.Impl'_Instance.top_sub.C_sub.c --

pub uninterp spec fn c_action_Output(Input1: i32, Input2: i32, Output: i32) -> i32;

/** "C fires": every written field is determined by the read scope;
  * everything else is framed.
  */
pub open spec fn c_fire(pre: SystemState, post: SystemState) -> bool
{
  post.top_output == c_action_Output(pre.top_a_output, pre.top_b_output, pre.top_output)
  && c_global_write_frame(pre, post)
}

} // verus!
